/**
 * Send Email Communication
 * Direct email to student with current status
 */
window.sendEmailCommunication = function(requestId, studentName, studentEmail) {
    const model = window.AdminHubModel;
    const request = model.requests.find(r => r.id === requestId);
    
    if (!request) {
        alert('? Request not found');
        return;
    }

    // Generate status-specific email
    let emailSubject = '';
    let emailBody = '';
    
    if (request.status === 'Pending Review') {
        emailSubject = `?? Your request is being reviewed - ${requestId}`;
        emailBody = `Dear ${studentName},\n\nYour request is currently under review.\n\nExpected response: Within 5 working days.\n\nThank you for your patience.`;
    } else if (request.status === 'Approved') {
        emailSubject = `? Your request has been approved - ${requestId}`;
        emailBody = `Dear ${studentName},\n\nGreat news! Your request has been approved.\n\nYou can now proceed with the next steps.\n\nThank you!`;
    } else if (request.status === 'Rejected') {
        emailSubject = `? Your request requires action - ${requestId}`;
        emailBody = `Dear ${studentName},\n\nYour request requires additional information.\n\nPlease contact the department for guidance.\n\nDepartment: ${request.unitInfo.name}`;
    }

    alert(`? Email Sent!\n\nTo: ${studentEmail}\nSubject: ${emailSubject}\n\n${emailBody}\n\n?? Email notification has been sent to the student and logged in the system.`);
    console.log(`?? Email sent to ${studentEmail} for request ${requestId}`);
};

// ============================================
// STUDENT TICKET ACTIONS (Approve/Reject)
// ============================================

// Helper: call Edge Function to send ticket status email
async function _sendTicketEmail(ticket, status, adminNotes) {
    const studentEmail = ticket.studentEmail || ticket.student_email || '';
    if (!studentEmail) {
        console.warn('📧 Cannot send email: no student_email on ticket', ticket.ticketId);
        alert(`⚠️ Email not sent: ticket has no student email.\nTicket ID: ${ticket.ticketId}`);
        return;
    }
    try {
        const fnUrl = 'https://ayswzpiennofznmpooia.supabase.co/functions/v1/ticket-notification';
        const anonKey = typeof SUPABASE_CONFIG !== 'undefined' ? SUPABASE_CONFIG.anonKey : '';
        const res = await fetch(fnUrl, {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
                'Authorization': `Bearer ${anonKey}`,
                'apikey': anonKey,
            },
            body: JSON.stringify({
                record: {
                    ticket_id: ticket.ticketId,
                    student_email: studentEmail,
                    title: ticket.title,
                    status: status,
                    priority: ticket.priority,
                    department: ticket.department,
                    admin_notes: adminNotes || ''
                },
                old_record: { status: 'submitted' }
            })
        });
        const data = await res.json().catch(() => ({}));
        if (res.ok) {
            console.log(`📧 Email sent (${status}) to ${studentEmail}`, data);
        } else {
            console.error(`📧 Email failed:`, data);
            alert(`⚠️ Email notification failed.\nStatus: ${res.status}\nError: ${JSON.stringify(data)}`);
        }
    } catch (e) {
        console.error('📧 Email fetch error:', e.message);
        alert(`⚠️ Email notification error: ${e.message}`);
    }
}

window.approveTicket = async function(ticketId, studentId, studentEmail) {
    if (!confirm(`✅ Approve this ticket?\n\nTicket: ${ticketId}\nStudent: ${studentId}`)) {
        return;
    }

    try {
        // Find the ticket
        const ticket = StudentPortalManager.tickets.find(t => t.ticketId === ticketId);
        if (!ticket) {
            alert('❌ Ticket not found');
            return;
        }

        // Update ticket status in memory
        ticket.status = 'approved';
        ticket.lastUpdate = new Date();

        // Remove from StudentPortalManager immediately so re-render doesn't show it
        StudentPortalManager.tickets = StudentPortalManager.tickets.filter(t => t.ticketId !== ticketId);

        // Remove from localStorage so it doesn't resurface
        const lsKey = 'studentSubmittedTickets';
        const lsTickets = JSON.parse(localStorage.getItem(lsKey) || '[]').filter(t => t.ticketId !== ticketId);
        localStorage.setItem(lsKey, JSON.stringify(lsTickets));

        // 💾 Save status update to Supabase
        if (typeof window.SupabaseService !== 'undefined') {
            try {
                await window.SupabaseService.db.updateTicketStatus(studentId, ticketId, 'approved');
                console.log('✅ Ticket status updated in Supabase');
            } catch (error) {
                console.error('❌ Error updating ticket in Supabase:', error);
            }
        }

        // Send approval email via Edge Function
        await _sendTicketEmail(ticket, 'approved', '');
        console.log(`✅ Ticket approved: ${ticketId}`);
        
        // ?? Update clinical tracking if this is a clinical issue
        if (ticket.requestType === 'clinical' && typeof StudentPortalManager.clinicalTracking !== 'undefined') {
            StudentPortalManager.clinicalTracking.updateStats();
            console.log(`?? Clinical stats updated`);
        }
        
        // ?? Update community services tracking if this is an event/conference request
        if (ticket.requestType === 'event-participation' && typeof StudentPortalManager.communityServicesTracking !== 'undefined') {
            StudentPortalManager.communityServicesTracking.updateStats();
            console.log(`?? Community services stats updated`);
        }
        
        // ✅ Immediately refresh dashboard to remove approved ticket from view
        if (window.app && typeof window.app.renderAdminHub === 'function') {
            await window.app.renderAdminHub();
        }

        // Show success message AFTER refresh (so ticket already disappeared)
        alert(`✅ Ticket Approved!\n\n📧 Email notification sent to ${studentEmail}\n\nThe ticket has been moved to Request Tracking Dashboard.`);
    } catch (error) {
        console.error('? Error approving ticket:', error);
        alert(`? Error: ${error.message}`);
    }
};

window.rejectTicket = async function(ticketId, studentId, studentEmail) {
    const rejectReason = prompt('❌ Reject ticket. Please provide a reason:');
    if (!rejectReason) {
        return; // User cancelled
    }

    try {
        // Find the ticket
        const ticket = StudentPortalManager.tickets.find(t => t.ticketId === ticketId);
        if (!ticket) {
            alert('❌ Ticket not found');
            return;
        }

        // Update ticket status in memory
        ticket.status = 'rejected';
        ticket.lastUpdate = new Date();
        ticket.rejectionReason = rejectReason;

        // Remove from StudentPortalManager immediately so re-render doesn't show it
        StudentPortalManager.tickets = StudentPortalManager.tickets.filter(t => t.ticketId !== ticketId);

        // Remove from localStorage so it doesn't resurface
        const lsKey = 'studentSubmittedTickets';
        const lsTickets = JSON.parse(localStorage.getItem(lsKey) || '[]').filter(t => t.ticketId !== ticketId);
        localStorage.setItem(lsKey, JSON.stringify(lsTickets));

        // 💾 Save status update to Supabase
        if (typeof window.SupabaseService !== 'undefined') {
            try {
                await window.SupabaseService.db.updateTicketStatus(studentId, ticketId, 'rejected');
                console.log('✅ Ticket status updated in Supabase');
            } catch (error) {
                console.error('❌ Error updating ticket in Supabase:', error);
            }
        }

        // Send rejection email via Edge Function
        await _sendTicketEmail(ticket, 'rejected', rejectReason);
        console.log(`❌ Ticket rejected: ${ticketId}`);
        
        // ?? Update clinical tracking if this is a clinical issue
        if (ticket.requestType === 'clinical' && typeof StudentPortalManager.clinicalTracking !== 'undefined') {
            StudentPortalManager.clinicalTracking.updateStats();
            console.log(`?? Clinical stats updated`);
        }
        
        // ?? Update community services tracking if this is an event/conference request
        if (ticket.requestType === 'event-participation' && typeof StudentPortalManager.communityServicesTracking !== 'undefined') {
            StudentPortalManager.communityServicesTracking.updateStats();
            console.log(`?? Community services stats updated`);
        }
        
        // ✅ Immediately refresh dashboard to remove rejected ticket from view
        if (window.app && typeof window.app.renderAdminHub === 'function') {
            await window.app.renderAdminHub();
        }

        // Show success message AFTER refresh (so ticket already disappeared)
        alert(`❌ Ticket Rejected\n\n📧 Email notification sent to ${studentEmail}\n\nReason: ${rejectReason}\n\nThe ticket has been moved to Request Tracking Dashboard.`);
    } catch (error) {
        console.error('? Error rejecting ticket:', error);
        alert(`? Error: ${error.message}`);
    }
};

